INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $t$Masalah: Arduino Lupa Waktu Setiap Mati Listrik$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $t$Arduino tidak punya jam internal yang bertahan saat catu daya dicabut. Setiap restart, waktu kembali ke nol, sehingga proyek seperti lampu otomatis, jadwal penyiram tanaman, atau pencatat data tidak bisa berjalan sesuai jadwal. Solusinya adalah modul RTC (Real Time Clock) DS3231: sebuah chip jam yang ditenagai baterai koin CR2032 dan tetap menghitung detik, menit, jam, tanggal, hingga tahun meski Arduino dimatikan.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $t$Penjelasan: Cara Kerja DS3231$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $t$DS3231 adalah chip RTC presisi tinggi dengan osilator kristal internal yang dikompensasi suhu, sehingga penyimpangannya hanya sekitar plus-minus 2 menit per tahun, jauh lebih akurat dibanding DS1307. Modul berkomunikasi lewat I2C (dua kabel SDA dan SCL) dan menyimpan waktu dalam register BCD. Baterai CR2032 menjaga jam tetap berjalan hingga bertahun-tahun.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $t$Alat dan Bahan$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$t$Arduino Uno/Nano$t$, $t$Modul RTC DS3231$t$, $t$Baterai CR2032 (biasanya sudah termasuk)$t$, $t$Kabel jumper secukupnya$t$, $t$Komputer dengan Arduino IDE + library RTClib$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $t$Langkah: Merangkai dan Mengatur Waktu$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$t$Hubungkan VCC modul ke 5V Arduino, GND ke GND, SDA ke A4, SCL ke A5 (Uno/Nano).$t$, $t$Pasang baterai CR2032 pada modul.$t$, $t$Instal library RTClib (oleh Adafruit) lewat Library Manager.$t$, $t$Jalankan contoh sketch ds3231, lalu atur waktu dengan perintah rtc.adjust(DateTime(__DATE__, __TIME__)) sekali saja.$t$, $t$Upload sketch pembaca waktu dan buka Serial Monitor untuk melihat jam berjalan.$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $t$Risiko dan Kesalahan Umum$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$t$Waktu tidak berubah: periksa kabel SDA/SCL tertukar atau library belum terinstal.$t$, $t$Jam berhenti saat mati: baterai CR2032 habis atau tidak terpasang dengan benar.$t$, $t$Waktu melompat aneh: jangan panggil rtc.adjust() setiap loop, cukup sekali saat pengaturan awal.$t$, $t$Alamat I2C bentrok dengan sensor lain: gunakan I2C scanner untuk memastikan alamat 0x68 terbaca.$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $t$Pemeriksaan Hasil$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $t$Cabut catu daya Arduino selama beberapa menit, lalu sambungkan kembali dan buka Serial Monitor. Jika jam menunjukkan waktu yang benar dan terus bertambah, modul bekerja. Catat tanggal dan bandingkan seminggu kemudian untuk memastikan akurasinya.$t$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $t$Masalah: Nasi Uduk Kurang Gurih atau Terlalu Lembek$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $t$Nasi uduk yang enak harus gurih merata, pulen, dan aromatik. Kegagalan umum adalah santan kurang sehingga hambar, air terlalu banyak sehingga lembek, atau santan pecah sehingga berminyak. Dengan takaran dan teknik yang tepat, nasi uduk rumahan bisa seenak buatan penjual legendaris.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $t$Penjelasan: Kunci Kegurihan Nasi Uduk$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $t$Gurihnya nasi uduk berasal dari santan kelapa yang meresap saat beras dimasak. Aroma khas datang dari daun salam, serai, dan lengkuas. Beras pera (tidak terlalu pulen) lebih cocok karena butirannya tetap utuh dan tidak lengket setelah dimasak dengan santan.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $t$Bahan (untuk 4-5 porsi)$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$t$500 gram beras, cuci bersih$t$, $t$400 ml santan dari setengah butir kelapa$t$, $t$300 ml air$t$, $t$2 lembar daun salam$t$, $t$2 batang serai, memarkan$t$, $t$3 cm lengkuas, memarkan$t$, $t$1 sendok teh garam$t$, $t$Lauk pendamping: ayam goreng, telur balado, tempe orek, emping, sambal kacang$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $t$Langkah Memasak$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$t$Masak santan, air, daun salam, serai, lengkuas, dan garam sambil diaduk hingga mendidih agar santan tidak pecah.$t$, $t$Masukkan beras, aduk rata, masak dengan api kecil hingga santan terserap habis (metode aron).$t$, $t$Kukus nasi aron selama 30-40 menit hingga matang dan pulen.$t$, $t$Angkat, buang rempah daunnya, aduk perlahan agar uap keluar dan butiran tidak menggumpal.$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $t$Risiko dan Kesalahan Umum$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$t$Santan pecah: selalu aduk saat merebus santan dan jangan tinggalkan.$t$, $t$Nasi lembek: kurangi air 50 ml jika beras yang dipakai jenis pulen.$t$, $t$Hambar: tambah garam sedikit demi sedikit, santan encer butuh garam lebih banyak.$t$, $t$Cepat basi: pastikan nasi benar-benar matang saat dikukus dan simpan dalam wadah tertutup.$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $t$Penyajian$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $t$Sajikan nasi uduk hangat dengan ayam goreng, telur balado, tempe orek, emping melinjo, dan sambal kacang. Tambahkan irisan mentimun dan bawang goreng untuk kesegaran. Sisa nasi uduk bisa digoreng keesokan harinya menjadi nasi goreng uduk yang tak kalah lezat.$t$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $t$Gas Mulia yang Berbahaya$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $t$Radon (Rn, nomor atom 86) adalah gas mulia yang radioaktif. Tidak berwarna, tidak berbau, dan tidak berasa, tetapi meluruh memancarkan partikel alfa yang berbahaya bagi paru-paru. Ia terbentuk alami dari peluruhan uranium dan torium di dalam tanah dan batuan.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $t$Dari Mana Radon Berasal$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $t$Uranium yang ada di tanah dan batuan meluruh menjadi radium, lalu menjadi radon. Gas ini merembes naik melalui retakan fondasi, celah lantai, dan pori-pori beton, lalu menumpuk di ruangan tertutup terutama di lantai dasar dan ruang bawah tanah yang ventilasinya buruk.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $t$Bahaya bagi Kesehatan$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $t$Saat terhirup, radon dan produk luruhannya menempel di saluran pernapasan dan memancarkan radiasi alfa langsung ke jaringan paru. Badan kesehatan dunia menempatkan radon sebagai penyebab kanker paru kedua terbesar setelah rokok, terutama berbahaya bagi perokok karena efeknya saling memperkuat.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $t$Cara Mendeteksi dan Mengurangi$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $t$Kadar radon diukur dengan alat detektor khusus dalam satuan becquerel per meter kubik. Jika kadarnya tinggi, solusinya sederhana: perbaiki ventilasi, tutup retakan fondasi, dan pasang sistem depresurisasi tanah. Rumah di daerah berbatu granit umumnya berisiko lebih tinggi.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $t$Manfaat Terbatas dalam Kedokteran$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $t$Di masa lalu radon pernah dipakai untuk terapi radiasi, tetapi kini penggunaannya sangat dibatasi karena risikonya. Saat ini radon lebih banyak dipelajari sebagai penanda geologi untuk memantau aktivitas sesar dan gunung berapi.$t$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $t$Latar Belakang$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $t$Setelah Revolusi Bunga di Portugal tahun 1974, pemerintah Lisbon memutuskan melepas koloni-koloninya termasuk Timor Portugis. Di tengah kekosongan kekuasaan muncul tiga partai: UDT, Fretilin, dan Apodeti yang berbeda pandangan soal masa depan wilayah itu. Fretilin kemudian mendeklarasikan kemerdekaan sepihak pada 28 November 1975, sementara Indonesia khawatir akan berdirinya negara berhaluan kiri di perbatasannya.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $t$Jalannya Operasi$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $t$Pada 7 Desember 1975 Indonesia melancarkan Operasi Seroja, operasi gabungan darat, laut, dan udara untuk menguasai Dili. Pertempuran berlanjut ke daerah pedalaman melawan pasukan Falintil, sayap bersenjata Fretilin, yang melakukan perang gerilya di pegunungan selama bertahun-tahun.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $t$Integrasi dan Pemerintahan$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $t$Pada 17 Juli 1976 Timor Timur resmi diintegrasikan sebagai provinsi ke-27 Indonesia melalui undang-undang. Pemerintah membangun infrastruktur, sekolah, dan fasilitas kesehatan, tetapi perlawanan bersenjata dan gerakan bawah tanah terus berlangsung.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $t$Dampak dan Korban$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $t$Konflik berkepanjangan menimbulkan korban jiwa yang besar dari kedua pihak serta penderitaan warga sipil akibat pertempuran, kelaparan, dan penyakit. Peristiwa seperti pembantaian Santa Cruz 1991 menarik perhatian dunia internasional terhadap situasi di sana.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $t$Jalan Menuju Referendum$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $t$Setelah perubahan politik di Indonesia pada 1998, pemerintah menawarkan otonomi khusus atau kemerdekaan lewat referendum 30 Agustus 1999. Mayoritas rakyat memilih merdeka, dan pada 20 Mei 2002 Timor Leste resmi menjadi negara merdeka dengan nama Republik Demokratik Timor Leste.$t$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $t$Tujuan Pembelajaran$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $t$Setelah mempelajari materi ini, peserta didik mampu menjelaskan pengertian mitigasi bencana, mengidentifikasi jenis-jenis bencana di Indonesia, menguraikan siklus penanggulangan bencana, serta merancang tindakan kesiapsiagaan di lingkungan sekolah dan rumah.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $t$Pengertian Mitigasi Bencana$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $t$Mitigasi adalah upaya mengurangi risiko dan dampak bencana sebelum bencana terjadi. Berbeda dengan tanggap darurat yang dilakukan saat bencana berlangsung, mitigasi bersifat pencegahan, misalnya membangun rumah tahan gempa, membuat peta jalur evakuasi, dan menanam mangrove untuk menahan abrasi.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $t$Jenis Bencana di Indonesia$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$t$Bencana geologi: gempa bumi, tsunami, letusan gunung api, tanah longsor.$t$, $t$Bencana hidrometeorologi: banjir, kekeringan, angin puting beliung, kebakaran hutan.$t$, $t$Bencana non-alam: wabah penyakit, kegagalan teknologi, konflik sosial.$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $t$Siklus Penanggulangan Bencana$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $t$Penanggulangan bencana berjalan dalam siklus: mitigasi dan kesiapsiagaan sebelum bencana, tanggap darurat saat bencana, lalu rehabilitasi dan rekonstruksi sesudahnya. Setiap tahap saling berkaitan dan hasilnya dievaluasi untuk memperbaiki kesiapsiagaan berikutnya.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $t$Peran Masyarakat dan Teknologi$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $t$Masyarakat berperan melalui kesiapsiagaan keluarga, simulasi evakuasi, dan kearifan lokal seperti rumah panggung di daerah banjir. Teknologi membantu lewat sistem peringatan dini tsunami (InaTEWS), aplikasi info BMKG, dan pemetaan daerah rawan bencana.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $t$Latihan Soal$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$t$Jelaskan perbedaan mitigasi struktural dan mitigasi non-struktural, beri masing-masing dua contoh!$t$, $t$Mengapa Indonesia rawan terhadap hampir semua jenis bencana? Kaitkan dengan letak geologis dan klimatologisnya.$t$, $t$Rancang rencana evakuasi sederhana untuk sekolahmu jika terjadi gempa bumi saat jam pelajaran!$t$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $t$Tujuan Pembelajaran$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $t$Setelah belajar, siswa dapat menjelaskan pengertian wudhu, menyebutkan rukun wudhu dengan benar, mempraktikkan tata cara wudhu secara berurutan, dan menyebutkan hal-hal yang membatalkan wudhu.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $t$Pengertian Wudhu$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $t$Wudhu adalah mensucikan diri dengan air pada anggota tubuh tertentu sebelum shalat dan ibadah lainnya. Allah berfirman dalam Al-Quran surat Al-Maidah ayat 6 tentang perintah berwudhu. Wudhu membuat tubuh bersih dan hati tenang sebelum menghadap Allah.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $t$Rukun Wudhu$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$t$Niat dalam hati karena Allah.$t$, $t$Membasuh wajah.$t$, $t$Membasuh kedua tangan sampai siku.$t$, $t$Mengusap sebagian kepala.$t$, $t$Membasuh kedua kaki sampai mata kaki.$t$, $t$Tertib, yaitu berurutan seperti di atas.$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $t$Tata Cara Wudhu Berurutan$t$));
